/* Generated by packages/tokens/scripts/build.mjs. Do not edit by hand. */

:root {
  --eui-radius-none: 0px;
  --eui-radius-sm: 0.375rem;
  --eui-radius-md: 0.5rem;
  --eui-radius-lg: 0.75rem;
  --eui-radius-full: 9999px;
  --eui-radius-base: var(--eui-radius-md);
  --eui-font-sans: "Geist Variable", "Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --eui-font-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --eui-border-width: 1px;
  --eui-duration-fast: 120ms;
  --eui-duration-base: 200ms;
  --eui-easing-out: cubic-bezier(0.2, 0, 0, 1);
  --eui-color-bg: #ffffff;
  --eui-color-surface: #fafafa;
  --eui-color-fg: #171717;
  --eui-color-fg-muted: #666666;
  --eui-color-border: #ebebeb;
  --eui-color-border-strong: #8f8f8f;
  --eui-color-hover: #f2f2f2;
  --eui-color-ring: #171717;
  --eui-color-accent: #171717;
  --eui-color-accent-fg: #fafafa;
  --eui-color-accent-hover: color-mix(in oklab, var(--eui-color-accent) 88%, var(--eui-color-bg));
  --eui-color-danger: #d1242f;
  --eui-color-danger-fg: #ffffff;
  --eui-color-danger-hover: color-mix(in oklab, var(--eui-color-danger) 88%, var(--eui-color-bg));
  color-scheme: light;
}

[data-theme="light"] {
  --eui-color-bg: #ffffff;
  --eui-color-surface: #fafafa;
  --eui-color-fg: #171717;
  --eui-color-fg-muted: #666666;
  --eui-color-border: #ebebeb;
  --eui-color-border-strong: #8f8f8f;
  --eui-color-hover: #f2f2f2;
  --eui-color-ring: #171717;
  --eui-color-accent: #171717;
  --eui-color-accent-fg: #fafafa;
  --eui-color-accent-hover: color-mix(in oklab, var(--eui-color-accent) 88%, var(--eui-color-bg));
  --eui-color-danger: #d1242f;
  --eui-color-danger-fg: #ffffff;
  --eui-color-danger-hover: color-mix(in oklab, var(--eui-color-danger) 88%, var(--eui-color-bg));
  color-scheme: light;
}

[data-theme="dark"] {
  --eui-color-bg: #000000;
  --eui-color-surface: #0a0a0a;
  --eui-color-fg: #ededed;
  --eui-color-fg-muted: #a1a1a1;
  --eui-color-border: #1f1f1f;
  --eui-color-border-strong: #6e6e6e;
  --eui-color-hover: #1a1a1a;
  --eui-color-ring: #ededed;
  --eui-color-accent: #ededed;
  --eui-color-accent-fg: #0a0a0a;
  --eui-color-accent-hover: color-mix(in oklab, var(--eui-color-accent) 88%, var(--eui-color-bg));
  --eui-color-danger: #ff6369;
  --eui-color-danger-fg: #000000;
  --eui-color-danger-hover: color-mix(in oklab, var(--eui-color-danger) 88%, var(--eui-color-bg));
  color-scheme: dark;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --eui-color-bg: #000000;
    --eui-color-surface: #0a0a0a;
    --eui-color-fg: #ededed;
    --eui-color-fg-muted: #a1a1a1;
    --eui-color-border: #1f1f1f;
    --eui-color-border-strong: #6e6e6e;
    --eui-color-hover: #1a1a1a;
    --eui-color-ring: #ededed;
    --eui-color-accent: #ededed;
    --eui-color-accent-fg: #0a0a0a;
    --eui-color-accent-hover: color-mix(in oklab, var(--eui-color-accent) 88%, var(--eui-color-bg));
    --eui-color-danger: #ff6369;
    --eui-color-danger-fg: #000000;
    --eui-color-danger-hover: color-mix(in oklab, var(--eui-color-danger) 88%, var(--eui-color-bg));
    color-scheme: dark;
  }
}

/* Base layer. Scoped to .eui-root so it never leaks into a host page's styles. */

.eui-root {
  font-family: var(--eui-font-sans);
  color: var(--eui-color-fg);
  background-color: var(--eui-color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

.eui-root *,
.eui-root *::before,
.eui-root *::after {
  box-sizing: border-box;
}

.eui-root :focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}
